"""Render docs/EXTERNAL_BENCH.md and the README external-bench block from the results files.

Usage: python bench/external/render_external.py
Numbers are never typed by hand (AGENTS.md rule 6); tests fail if the generated text is stale.
"""

from __future__ import annotations

import json
import sys
from pathlib import Path
from typing import Any

HERE = Path(__file__).resolve().parent
REPO = HERE.parent.parent
START, END = "<!-- external:start -->", "<!-- external:end -->"


def _fmt(v: Any) -> str:
    return "n/a" if v is None else str(v)


def summary_table(res: dict[str, Any]) -> list[str]:
    m = res["metrics"]
    n = res["tasks"]
    lines = [
        "| check | ground truth | result |",
        "|---|---|---|",
    ]
    for c, v in m["per_check"].items():
        if c == "C004":
            text = (
                f"precision {_fmt(v['precision'])} ({v['confirmed']} of "
                f"{v['survivors_judged_by_oracle']} surviving mutants rejected by HumanEval+); "
                f"recall {_fmt(v['recall'])}"
            )
            rd = v.get("recall_detail")
            if rd:
                text += f" ({rd['weak_tasks_found_at_budget']} of {rd['weak_tasks']} weak tasks)"
        else:
            text = (
                f"{v['loud_findings']} error/warning findings on {v['tasks_with_loud_findings']} "
                f"of {n} tasks; precision and recall not measurable (no labels)"
            )
        lines.append(f"| {c} | {v['ground_truth']} | {text} |")
    return lines


def render(full: dict[str, Any], sample: dict[str, Any]) -> str:
    m = full["metrics"]
    lines = [
        "# External bench results",
        "",
        "Generated by `bench/external/render_external.py` from `bench/external/results.json` "
        "and `bench/external/sample-results.json`. Do not edit by hand. Method and ground truth: "
        "[bench/external/README.md](../bench/external/README.md). Licences: "
        "[bench/LICENSES.md](../bench/LICENSES.md).",
        "",
        "## Datasets",
        "",
        "| dataset | licence | source | role |",
        "|---|---|---|---|",
    ]
    for d in full["datasets"]:
        lines.append(f"| {d['name']} | {d['licence']} | {d['source']} | {d['role']} |")
    lines += [
        "",
        f"## Full run: {full['tasks']} tasks (aethens {full['tool_version']}, seed {full['seed']}, "
        f"budget {full['budget']}, exhaustive mutation {'on' if full['exhaustive'] else 'off'})",
        "",
        f"Checks run: {', '.join(full['checks'])} (C003 needs labelled candidates, which "
        "HumanEval does not have).",
        "",
        *summary_table(full),
        "",
        f"Tasks whose original HumanEval canonical solution fails the HumanEval+ oracle "
        f"(oracle unusable, excluded from C004 precision and recall): "
        f"{len(m['tasks_without_oracle'])}"
        + (f" ({', '.join(m['tasks_without_oracle'])})" if m["tasks_without_oracle"] else "")
        + ".",
        "",
        "### Every error/warning finding on the presumed-clean checks",
        "",
    ]
    listed = False
    for c, v in m["per_check"].items():
        for f in v["loud_finding_list"]:
            listed = True
            lines.append(f"- {c} `{f['task']}` ({f['severity']}): {f['title']}")
    if not listed:
        lines.append("- none")
    lines += ["", "### Tasks without a usable oracle", ""]
    no_oracle = [r for r in full["per_task"] if not r["oracle_accepts_gold"]]
    for r in no_oracle:
        lines.append(
            f"- `{r['task']}`: the original HumanEval canonical solution on the HumanEval+ tests: "
            f"{r.get('oracle_gold_run', 'failed')}"
        )
    if not no_oracle:
        lines.append("- none")
    lines += [
        "",
        f"## Offline sample: {sample['tasks']} tasks (run by `make check`)",
        "",
        *summary_table(sample),
        "",
    ]
    return "\n".join(lines)


def readme_block(full: dict[str, Any]) -> str:
    c004 = full["metrics"]["per_check"].get("C004", {})
    loud = {c: v["loud_findings"] for c, v in full["metrics"]["per_check"].items() if c != "C004"}
    rd = c004.get("recall_detail") or {}
    lines = [
        START,
        f"Generated from `bench/external/results.json` by `bench/external/render_external.py` "
        f"(aethens {full['tool_version']}, seed {full['seed']}, budget {full['budget']}).",
        "",
        f"On {full['tasks']} HumanEval tasks (MIT), judged by EvalPlus's HumanEval+ tests "
        "(Apache-2.0) as an outside oracle:",
        "",
        f"- C004 precision {_fmt(c004.get('precision'))}: {c004.get('confirmed')} of "
        f"{c004.get('survivors_judged_by_oracle')} mutants that HumanEval's own tests accepted "
        "are rejected by HumanEval+.",
        f"- C004 recall {_fmt(c004.get('recall'))} relative to exhaustive mutation "
        f"({rd.get('weak_tasks_found_at_budget')} of {rd.get('weak_tasks')} weak tasks found at "
        f"budget {full['budget']}).",
        "- Error/warning findings on checks without labels in this data (presumed clean): "
        + ", ".join(f"{c} {n}" for c, n in loud.items())
        + ". Details: [docs/EXTERNAL_BENCH.md](docs/EXTERNAL_BENCH.md).",
        END,
    ]
    return "\n".join(lines)


def main() -> int:
    full = json.loads((HERE / "results.json").read_text(encoding="utf-8"))
    sample = json.loads((HERE / "sample-results.json").read_text(encoding="utf-8"))
    (REPO / "docs" / "EXTERNAL_BENCH.md").write_text(render(full, sample), encoding="utf-8")
    readme_path = REPO / "README.md"
    readme = readme_path.read_text(encoding="utf-8")
    if START not in readme or END not in readme:
        print("README.md has no external-bench markers", file=sys.stderr)
        return 2
    head, rest = readme.split(START, 1)
    _, tail = rest.split(END, 1)
    readme_path.write_text(head + readme_block(full) + tail, encoding="utf-8")
    print("docs/EXTERNAL_BENCH.md and the README external block updated")
    return 0


if __name__ == "__main__":
    sys.exit(main())
